function topic(kind: EuropeGuideTopic, sourceIds: string[], facts: NativeBrief) {
  return {
    sourceIds,
    copy: Object.fromEntries(
      locales.map((locale, i) => [locale, `${facts[i]} ${decision[kind][i]}`]),
    ) as Record<EuropeBlogLocale, string>,
  };
}

const source = (id: string, label: string, url: string) => ({
  id,
  label,
  url,
  checkedAt: "2026-10-27",
});

